function borrow(a: f64[]): ReadSpan<f64> {
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  return v;
}
export function entry(v0: ReadSpan<f64>, v1: ReadSpan<f64>, v2: ReadSpan<f64>, v3: ReadSpan<f64>, v4: ReadSpan<f64>, v5: ReadSpan<f64>, v6: ReadSpan<f64>, v7: ReadSpan<f64>): f64 {
  const a: f64[] = [1];
  const w0: ReadSpan<f64> = borrow(a);
  const w1: ReadSpan<f64> = borrow(a);
  const w2: ReadSpan<f64> = borrow(a);
  const w3: ReadSpan<f64> = borrow(a);
  const w4: ReadSpan<f64> = borrow(a);
  const w5: ReadSpan<f64> = borrow(a);
  const w6: ReadSpan<f64> = borrow(a);
  const w7: ReadSpan<f64> = borrow(a);
  const w8: ReadSpan<f64> = borrow(a);
  const w9: ReadSpan<f64> = borrow(a);
  const w10: ReadSpan<f64> = borrow(a);
  const w11: ReadSpan<f64> = borrow(a);
  const w12: ReadSpan<f64> = borrow(a);
